<script lang="ts">
 import type {Snippet} from 'svelte';
 import {timeAudience,clockLabel,type TimePerson,type Window,type TimeAudienceSummary} from './time-audience';
 import {platformClass} from './period';
 import Help from './Help.svelte';
 let {categoryFilter,windows,people,timezone='Europe/Moscow',onPerson,summary=[]}:{categoryFilter:Snippet<[string]>;windows:Window[];people:TimePerson[];timezone?:string;summary?:TimeAudienceSummary[];onPerson:(id:string)=>void}=$props();
 let day=$state('all'),hour=$state<number|null>(null),resolution=$state(60),selected=$state<number|null>(null);
 $effect(()=>{resolution=hour===null?60:15;});
 const buckets=$derived(summary.length?timeAudience([],[],timezone,resolution,day,hour).map(empty=>{const bucket=summary.find(b=>b.day===day&&b.resolution===resolution&&b.minute===empty.minute);return bucket??{...empty,streams:0,people:[]};}):timeAudience(windows,people,timezone,resolution,day,hour).map(b=>({...b,streams:b.streams.size,people:[...b.people].map(([id,sessions])=>({id,visits:sessions.size}))})));
 const chosen=$derived(buckets.find(b=>b.minute===selected));
 const maximum=$derived(Math.max(1,...buckets.map(b=>(b.averageAudience??0))));
 const averageLabel=(value:number|null)=>value===null?'нет эфиров':value.toLocaleString('ru-RU',{maximumFractionDigits:2});
 const byId=$derived(new Map(people.map(p=>[p.id,p])));
 const visitors=$derived(chosen?chosen.people.map(({id,visits}:{id:string;visits:number})=>({person:byId.get(id)!,visits,total:chosen.streams})).sort((a,b)=>b.visits-a.visits||a.person.name.localeCompare(b.person.name)):[]);
 $effect(()=>{void day;void hour;void resolution;selected=null;});
</script>
<section class="panel time-audience"><header><h2>Кто бывает в это время</h2><Help id="time-attendance-help" label="О явке по времени" text="Высота столбца — средняя активная аудитория по имеющимся сигналам: суммарное время присутствия людей / время эфиров в этом интервале. Повторные сигналы и пересечения площадок одного человека не суммируются. Частые и длинные эфиры сами по себе не повышают среднее. Будни — понедельник–пятница, выходные — суббота и воскресенье по часовому поясу аналитики. Это активность известных людей, а не число всех зрителей. Явка = число стримов с сигналом этого человека в выбранном интервале / число стримов, шедших в этом интервале. Один стрим учитывается один раз, даже если было несколько сообщений или перерывов. Учитываются наблюдения Twitch и сообщения; YouTube после сообщения — оценка активности, не подтверждение просмотра. Нажмите час, затем выберите детализацию до минуты."/></header>{@render categoryFilter("Категория явки")}
 <div class="controls"><label>День активности<select bind:value={day}><option value="all">Все дни</option><option value="weekdays">Будни</option><option value="weekends">Выходные</option>{#each ['пн','вт','ср','чт','пт','сб','вс'] as d}<option value={d}>{d}</option>{/each}</select></label><label>Час для детализации<select bind:value={hour}><option value={null}>Весь день</option>{#each Array.from({length:24},(_,i)=>i) as h}<option value={h}>{clockLabel(h*60)}</option>{/each}</select></label>{#if hour!==null}<label>Шаг активности<select bind:value={resolution}><option value={15}>15 минут</option><option value={5}>5 минут</option><option value={1}>1 минута</option></select></label>{/if}</div>
 <p class="small muted metric-caption">Средняя активная аудитория за время эфира</p>
 <div class="slots" style:grid-template-columns={`repeat(${buckets.length},minmax(0,1fr))`} aria-label="Таймлайн аудитории по времени суток">{#each buckets as b}<button class:chosen={selected===b.minute} disabled={!b.streams} aria-label={`${clockLabel(b.minute)} · в среднем ${averageLabel(b.averageAudience)} · ${b.streams} стримов`} onclick={()=>selected=b.minute} title={`${clockLabel(b.minute)}: в среднем ${averageLabel(b.averageAudience)}, ${b.streams} стримов`}><i style:height={`${(b.averageAudience??0)/maximum*100}%`}></i>{#if buckets.length<=24}<span>{hour===null?Math.floor(b.minute/60):b.minute%60}</span>{/if}</button>{/each}</div>
 {#if chosen}<div class="slot-heading"><strong>{clockLabel(chosen.minute)}–{clockLabel(chosen.minute+resolution)} · {chosen.streams} стримов · в среднем {averageLabel(chosen.averageAudience)}</strong>{#if hour===null}<button class="outline small" onclick={()=>{hour=Math.floor(chosen.minute/60);resolution=15;}}>Подробно по минутам</button>{/if}</div>
 <div class="table-wrap compact-data"><table><thead><tr><th>Человек</th><th>Явка в это время</th><th>Посещено / шло эфиров</th></tr></thead><tbody>{#each visitors as v}<tr><td><button class={`text-button ${platformClass(v.person.sources??[v.person.source??''])}`} onclick={()=>onPerson(v.person.id)}>{v.person.name}</button></td><td>{Math.round(v.visits/v.total*100)}%</td><td>{v.visits} / {v.total}</td></tr>{/each}</tbody></table></div>{#if !visitors.length}<p class="empty-small">Персональных сигналов в этом интервале нет.</p>{/if}{:else}<p class="small muted hint">Нажмите столбец: увидите людей и их явку среди эфиров в это время.</p>{/if}
</section>
<style>.metric-caption{padding:0 20px;margin:0}.controls{display:flex;flex-wrap:wrap;gap:12px;padding:16px 20px}label{display:grid;gap:6px;font-size:12px;flex:1 1 150px}select{width:100%;min-width:0}.slots{display:grid;gap:3px;align-items:end;height:130px;margin:12px 20px 32px}.slots button{position:relative;height:100%;padding:0;background:#222833;border:0;border-radius:3px}.slots button:disabled{opacity:.35}.slots button i{position:absolute;bottom:0;left:0;right:0;background:var(--teal);border-radius:3px}.slots button.chosen{outline:2px solid var(--accent)}.slots button span{position:absolute;top:100%;left:0;right:0;font-size:10px;color:var(--muted);margin-top:6px}.slot-heading{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;padding:12px 20px}.hint{padding:0 20px 16px}.compact-data{max-height:420px;overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid var(--border);font-size:12px}td button{white-space:normal;overflow-wrap:anywhere}.twitch{color:var(--twitch,#a970ff)}.youtube{color:var(--youtube,#ff5959)}</style>
